// The step that copies pdf.js's files into a package: the one line it changes in
// pdf.js's worker (and the build stopped when that line has moved), what it
// copies and leaves out, and that it writes nothing when its copies are current.
// Run against a stand-in for `pdfjs-dist` in a folder of its own; the package's
// own build test holds the real copy.
import {
  mkdirSync,
  mkdtempSync,
  readdirSync,
  readFileSync,
  rmSync,
  statSync,
  writeFileSync,
} from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

import { afterEach, beforeEach, describe, expect, it } from 'vitest';

import {
  generatePdfjs,
  HOOKED_FROM,
  HOOKED_TO,
  hookedHeader,
  hookWorker,
  installedPdfjs,
  usesPdfjs,
} from './gen-pdfjs.ts';

const WORKER = [
  'class WasmImage {',
  '  async #getJsInstance(imports) {',
  '    const { default: instantiate } = await import(',
  `    ${HOOKED_FROM}`,
  '  }',
  '}',
  '//# sourceMappingURL=pdf.worker.mjs.map',
].join('\n');

let into: string;
let pdfjs: string;
let pkg: string;

/** A stand-in for the installed `pdfjs-dist`, with a file of each kind and one of each not copied. */
function standIn(worker = WORKER): void {
  const files: Record<string, string> = {
    'build/pdf.worker.mjs': worker,
    'cmaps/78-H.bcmap': 'map',
    'cmaps/LICENSE': 'cmaps licence',
    'standard_fonts/FoxitSymbol.pfb': 'symbol',
    'standard_fonts/LiberationSans-Regular.ttf': 'sans',
    'standard_fonts/LICENSE_FOXIT': 'foxit licence',
    'wasm/openjpeg_nowasm_fallback.js': 'openjpeg',
    'wasm/jbig2_nowasm_fallback.js': 'jbig2',
    'wasm/openjpeg.wasm': 'wasm',
    'wasm/qcms_bg.wasm': 'wasm',
    'wasm/quickjs-eval.js': 'quickjs',
    'wasm/LICENSE_OPENJPEG': 'openjpeg licence',
    'wasm/LICENSE_PDFJS_JBIG2': 'jbig2 licence',
    'wasm/LICENSE_QCMS': 'qcms licence',
  };
  for (const [path, text] of Object.entries(files)) {
    mkdirSync(join(pdfjs, path, '..'), { recursive: true });
    writeFileSync(join(pdfjs, path), text);
  }
}

/** Every file under `dir`, relative to it. */
function filesUnder(dir: string): string[] {
  return readdirSync(dir, { recursive: true, withFileTypes: true })
    .filter((entry) => entry.isFile())
    .map((entry) => join(entry.parentPath, entry.name).slice(dir.length + 1))
    .sort();
}

beforeEach(() => {
  into = mkdtempSync(join(tmpdir(), 'gen-pdfjs-'));
  pdfjs = join(into, 'pdfjs-dist');
  pkg = join(into, 'pdf');
  mkdirSync(pkg);
});
afterEach(() => rmSync(into, { recursive: true, force: true }));

describe('hookWorker', () => {
  it('changes the one line, says so first, and drops the source map comment', () => {
    const hooked = hookWorker(WORKER, '9.9.9');
    const lines = hooked.split('\n');

    expect(lines[0]).toBe(hookedHeader('9.9.9'));
    expect(lines[0]).toMatch(/^\/\/ Generated by tooling\/gen-pdfjs\.ts from pdfjs-dist 9\.9\.9 /);
    expect(hooked).toContain(`    ${HOOKED_TO}`);
    expect(hooked.split(HOOKED_TO)).toHaveLength(2);
    expect(hooked).not.toContain('sourceMappingURL');
    // Everything else is as it was.
    expect(lines.slice(1).join('\n')).toBe(
      WORKER.replace(HOOKED_FROM, HOOKED_TO).replace(/\/\/# .*$/, '')
    );
  });

  it.each([
    ['not found', WORKER.replace(HOOKED_FROM, '`${wasmUrl}${name}`);')],
    ['found twice', `${WORKER}\n${HOOKED_FROM}`],
  ])('fails when the line is %s', (_, code) => {
    expect(() => hookWorker(code, '9.9.9')).toThrow(
      /imports of a decoder fallback where one was expected/
    );
  });
});

describe('generatePdfjs', () => {
  it('copies the maps, the fonts, the two fallbacks and their licences, and writes the hooked worker', () => {
    standIn();
    const generated = generatePdfjs(pkg, { dir: pdfjs, version: '9.9.9' });

    expect(generated).toEqual({ wrote: true, version: '9.9.9', files: 11 });
    expect(filesUnder(join(pkg, 'src'))).toEqual([
      'preview/pdfjs/cmaps/78-H.bcmap',
      'preview/pdfjs/cmaps/LICENSE',
      'preview/pdfjs/standard_fonts/FoxitSymbol.pfb',
      'preview/pdfjs/standard_fonts/LICENSE_FOXIT',
      'preview/pdfjs/standard_fonts/LiberationSans-Regular.ttf',
      'worker/pdfjs/LICENSE_OPENJPEG',
      'worker/pdfjs/LICENSE_PDFJS_JBIG2',
      'worker/pdfjs/jbig2_nowasm_fallback.js',
      'worker/pdfjs/openjpeg_nowasm_fallback.js',
      'worker/pdfjs/pdf.worker.d.mts',
      'worker/pdfjs/pdf.worker.mjs',
    ]);
    expect(readFileSync(join(pkg, 'src/worker/pdfjs/pdf.worker.mjs'), 'utf8')).toBe(
      hookWorker(WORKER, '9.9.9')
    );
  });

  it('writes nothing when its copies are current', () => {
    standIn();
    generatePdfjs(pkg, { dir: pdfjs, version: '9.9.9' });
    const before = statSync(join(pkg, 'src/preview/pdfjs/cmaps/78-H.bcmap')).mtimeMs;

    expect(generatePdfjs(pkg, { dir: pdfjs, version: '9.9.9' }).wrote).toBe(false);
    expect(statSync(join(pkg, 'src/preview/pdfjs/cmaps/78-H.bcmap')).mtimeMs).toBe(before);
  });

  it.each([
    ['another version is installed', () => '9.9.10'],
    [
      'a copy is missing',
      () => {
        rmSync(join(pkg, 'src/preview/pdfjs/standard_fonts/FoxitSymbol.pfb'));
        return '9.9.9';
      },
    ],
    [
      'a copy is not its source’s size',
      () => {
        writeFileSync(join(pdfjs, 'cmaps/78-H.bcmap'), 'a longer map');
        return '9.9.9';
      },
    ],
  ])('writes everything anew when %s, and leaves nothing stale', (_, change) => {
    standIn();
    generatePdfjs(pkg, { dir: pdfjs, version: '9.9.9' });
    writeFileSync(join(pkg, 'src/preview/pdfjs/cmaps/stale.bcmap'), 'gone from pdf.js');
    const version = change();

    expect(generatePdfjs(pkg, { dir: pdfjs, version }).wrote).toBe(true);
    expect(filesUnder(join(pkg, 'src/preview/pdfjs/cmaps'))).toEqual(['78-H.bcmap', 'LICENSE']);
    expect(readFileSync(join(pkg, 'src/worker/pdfjs/pdf.worker.mjs'), 'utf8')).toMatch(
      new RegExp(
        `^// Generated by tooling/gen-pdfjs\\.ts from pdfjs-dist ${version.replaceAll('.', '\\.')} `
      )
    );
  });

  it('fails, and leaves the last good copy, when an upgrade has moved the line', () => {
    standIn();
    generatePdfjs(pkg, { dir: pdfjs, version: '9.9.9' });
    writeFileSync(join(pdfjs, 'build/pdf.worker.mjs'), 'import(`${base}${name}`);');

    expect(() => generatePdfjs(pkg, { dir: pdfjs, version: '10.0.0' })).toThrow(
      /pdfjs-dist 10\.0\.0/
    );
    expect(readFileSync(join(pkg, 'src/worker/pdfjs/pdf.worker.mjs'), 'utf8')).toBe(
      hookWorker(WORKER, '9.9.9')
    );
  });
});

describe('the packages it runs for', () => {
  it('runs for a package that depends on pdfjs-dist, and no other', () => {
    writeFileSync(
      join(pkg, 'package.json'),
      JSON.stringify({ dependencies: { 'pdfjs-dist': '^6' } })
    );
    const other = join(into, 'other');
    mkdirSync(other);
    writeFileSync(
      join(other, 'package.json'),
      JSON.stringify({ devDependencies: { 'pdfjs-dist': '^6' } })
    );

    expect(usesPdfjs(pkg)).toBe(true);
    expect(usesPdfjs(other)).toBe(false);
    expect(usesPdfjs(join(into, 'nothing'))).toBe(false);
  });

  it('finds the pdfjs-dist the PDF format installs', () => {
    const { dir, version } = installedPdfjs(join(import.meta.dirname, '../packages/formats/pdf'));
    expect(dir).toMatch(/node_modules[\\/]pdfjs-dist$/);
    expect(version).toMatch(/^\d+\.\d+\.\d+$/);
  });
});
